1	export interface Item {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	}
7	
8	export interface QuoteStep {
9	  op: "quote";
10	  items: Item[];
11	}
12	
13	export interface Damage {
14	  itemType: string;
15	  amount: number;
16	}
17	
18	export interface Incident {
19	  cause: string;
20	  damages: Damage[];
21	}
22	
23	export interface ClaimStep {
24	  op: "claim";
25	  policy: number;
26	  incident: Incident;
27	}
28	
29	export type Step = QuoteStep | ClaimStep;
30	
31	export interface Customer {
32	  yearsWithMHPCO: number;
33	}
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export interface ScenarioOutput {
41	  results: unknown[];
42	}
43	
44	const PROCESSING_FEE = 5;
45	const INITIAL_ASSESSMENT_SURCHARGE_RATE = 0.1;
46	const LOYALTY_YEARS = 2;
47	const LOYALTY_DISCOUNT_RATE = 0.2;
48	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
49	
50	/** The MHPCO insures exactly these item types; anything else is unknown. */
51	interface ItemTypeTerms {
52	  basePremium: number;
53	  insuranceValue: number;
54	}
55	
56	const ITEM_TYPES: Record<string, ItemTypeTerms | undefined> = {
57	  sword: { basePremium: 100, insuranceValue: 1000 },
58	  amulet: { basePremium: 60, insuranceValue: 600 },
59	  staff: { basePremium: 80, insuranceValue: 800 },
60	  potion: { basePremium: 40, insuranceValue: 400 },
61	  rune: { basePremium: 25, insuranceValue: 250 },
62	  moonstone: { basePremium: 25, insuranceValue: 250 },
63	};
64	
65	const termsOfType = (type: string): ItemTypeTerms => {
66	  const terms = ITEM_TYPES[type];
67	  if (terms === undefined) {
68	    throw new Error(`unknown item type: ${type}`);
69	  }
70	  return terms;
71	};
72	
73	const basePremiumOfType = (type: string): number => termsOfType(type).basePremium;
74	
75	const insuranceValueOfType = (type: string): number => termsOfType(type).insuranceValue;
76	
77	const CURSE_SURCHARGE_RATE = 0.5;
78	const HIGH_ENCHANTMENT_LEVEL = 5;
79	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
80	
81	/** An item without an enchantment counts as enchantment 0. */
82	const enchantmentOf = (item: Item): number => item.enchantment ?? 0;
83	
84	const isCursed = (item: Item): boolean => item.cursed === true;
85	const isHighlyEnchanted = (item: Item): boolean =>
86	  enchantmentOf(item) >= HIGH_ENCHANTMENT_LEVEL;
87	
88	/** Item-specific modifiers apply to the base premium of the affected item only. */
89	const itemSurchargesOf = (item: Item): number => {
90	  const basePremium = basePremiumOfType(item.type);
91	  const curseSurcharge = isCursed(item) ? basePremium * CURSE_SURCHARGE_RATE : 0;
92	  const highEnchantmentSurcharge = isHighlyEnchanted(item)
93	    ? basePremium * HIGH_ENCHANTMENT_SURCHARGE_RATE
94	    : 0;
95	  return curseSurcharge + highEnchantmentSurcharge;
96	};
97	
98	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
99	const COMPONENT_BLOCK_SIZE = 3;
100	const COMPONENT_BLOCK_PREMIUM = 60;
101	
102	const isComponent = (type: string): boolean => COMPONENT_TYPES.has(type);
103	
104	const countByType = (items: Item[]): Map<string, number> => {
105	  const counts = new Map<string, number>();
106	  for (const item of items) {
107	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
108	  }
109	  return counts;
110	};
111	
112	/**
113	 * Items of one type are normally priced individually. The exception is
114	 * components: exactly 3 alike ones form a "building block" priced as a unit.
115	 */
116	const typeGroupPremium = (type: string, count: number): number =>
117	  isComponent(type) && count === COMPONENT_BLOCK_SIZE
118	    ? COMPONENT_BLOCK_PREMIUM
119	    : count * basePremiumOfType(type);
120	
121	const policyBasePremiumOf = (items: Item[]): number =>
122	  [...countByType(items)].reduce(
123	    (sum, [type, count]) => sum + typeGroupPremium(type, count),
124	    0,
125	  );
126	
127	const isLongStanding = (customer: Customer): boolean =>
128	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
129	
130	/** What the policy-wide modifiers are judged against, beyond the items themselves. */
131	interface QuoteContext {
132	  customer: Customer;
133	  isFollowUpContract: boolean;
134	}
135	
136	/**
137	 * Policy-wide modifiers are signed rates charged against the policy base
138	 * premium: surcharges positive, discounts negative.
139	 */
140	const policyModifierRateFor = (context: QuoteContext): number =>
141	  INITIAL_ASSESSMENT_SURCHARGE_RATE -
142	  (isLongStanding(context.customer) ? LOYALTY_DISCOUNT_RATE : 0) -
143	  (context.isFollowUpContract ? FOLLOW_UP_CONTRACT_DISCOUNT_RATE : 0);
144	
145	const itemSurchargesOfPolicy = (items: Item[]): number =>
146	  items.reduce((sum, item) => sum + itemSurchargesOf(item), 0);
147	
148	/** Kept as an exact fraction — only the final premium is rounded. */
149	const premiumBeforeRounding = (items: Item[], context: QuoteContext): number => {
150	  const policyBasePremium = policyBasePremiumOf(items);
151	  const policyModifiers = policyBasePremium * policyModifierRateFor(context);
152	  return policyBasePremium + itemSurchargesOfPolicy(items) + policyModifiers + PROCESSING_FEE;
153	};
154	
155	/** Rounded up, in the MHPCO's favour. */
156	const finalPremiumFor = (items: Item[], context: QuoteContext): number =>
157	  Math.ceil(premiumBeforeRounding(items, context));
158	
159	const DEDUCTIBLE = 100;
160	const CAP_MULTIPLIER = 2;
161	
162	const insuranceSumOf = (items: Item[]): number =>
163	  items.reduce((sum, item) => sum + insuranceValueOfType(item.type), 0);
164	
165	/** A policy created by a quote step, tracked so later claims can draw on it. */
166	interface Policy {
167	  items: Item[];
168	  remainingCap: number;
169	}
170	
171	/** The most a policy will ever pay out, across all claims against it. */
172	const capFor = (items: Item[]): number => insuranceSumOf(items) * CAP_MULTIPLIER;
173	
174	const openPolicyFor = (items: Item[]): Policy => ({ items, remainingCap: capFor(items) });
175	
176	const CLAIM_HIGH_ENCHANTMENT_LEVEL = 8;
177	const CLAIM_HIGH_ENCHANTMENT_RATE = 0.5;
178	
179	/**
180	 * Unrelated to the high-enchantment premium surcharge: that one is judged
181	 * against HIGH_ENCHANTMENT_LEVEL, this one against its own, higher threshold.
182	 */
183	const isHighlyEnchantedForClaims = (insuredItem: Item): boolean =>
184	  enchantmentOf(insuredItem) >= CLAIM_HIGH_ENCHANTMENT_LEVEL;
185	
186	/** The share of the damage the MHPCO reimburses, before the deductible. */
187	const reimbursementRateFor = (insuredItem: Item): number =>
188	  isHighlyEnchantedForClaims(insuredItem) ? CLAIM_HIGH_ENCHANTMENT_RATE : 1;
189	
190	const payoutForDamage = (damage: Damage, insuredItem: Item): number => {
191	  if (damage.amount < 0) {
192	    throw new Error(`damage amount must not be negative: ${String(damage.amount)}`);
193	  }
194	  return damage.amount * reimbursementRateFor(insuredItem) - DEDUCTIBLE;
195	};
196	
197	const insuredItemFor = (damage: Damage, policy: Policy): Item => {
198	  const insuredItem = policy.items.find((item) => item.type === damage.itemType);
199	  if (insuredItem === undefined) {
200	    throw new Error(`claim references uninsured item type ${damage.itemType}`);
201	  }
202	  return insuredItem;
203	};
204	
205	interface Settlement {
206	  payout: number;
207	  remainingCap: number;
208	}
209	
210	/**
211	 * Draws against the policy's remaining cap, which it depletes.
212	 * Rounded down, in the MHPCO's favour.
213	 */
214	/** Each damaged item must be one the policy actually covers, and only once. */
215	const rejectOverClaiming = (damages: Damage[], policy: Policy): void => {
216	  const insuredCounts = countByType(policy.items);
217	
218	  for (const [type, damaged] of countByType(
219	    damages.map((damage) => ({ type: damage.itemType })),
220	  )) {
221	    const insured = insuredCounts.get(type) ?? 0;
222	    if (damaged > insured) {
223	      throw new Error(`claim damages ${String(damaged)} ${type}(s) but only ${String(insured)} insured`);
224	    }
225	  }
226	};
227	
228	const settleClaim = (step: ClaimStep, policy: Policy): Settlement => {
229	  rejectOverClaiming(step.incident.damages, policy);
230	
231	  const claimed = step.incident.damages.reduce(
232	    (sum, damage) => sum + payoutForDamage(damage, insuredItemFor(damage, policy)),
233	    0,
234	  );
235	  const payout = Math.floor(Math.min(claimed, policy.remainingCap));
236	
237	  policy.remainingCap -= payout;
238	  return { payout, remainingCap: policy.remainingCap };
239	};
240	
241	const policyReferencedBy = (step: ClaimStep, policies: Map<number, Policy>): Policy => {
242	  const policy = policies.get(step.policy);
243	  if (policy === undefined) {
244	    throw new Error(`claim references unknown policy at step ${String(step.policy)}`);
245	  }
246	  return policy;
247	};
248	
249	export const runScenario = (scenario: Scenario): ScenarioOutput => {
250	  const policies = new Map<number, Policy>();
251	
252	  const results = scenario.steps.map((step, stepIndex) => {
253	    if (step.op === "claim") {
254	      return settleClaim(step, policyReferencedBy(step, policies));
255	    }
256	
257	    // Every quote but the first is a follow-up contract for this customer.
258	    const isFollowUpContract = policies.size > 0;
259	    policies.set(stepIndex, openPolicyFor(step.items));
260	
261	    return {
262	      premium: finalPremiumFor(step.items, { customer: scenario.customer, isFollowUpContract }),
263	    };
264	  });
265	
266	  return { results };
267	};
